      // presenting, so a plain push hides the selection (state kept).
      try { if (typeof fMulerSelectPush === "function") fMulerSelectPush(); } catch (ePP) {}
      return;
    }
    try { if (typeof fMulerSelectPush === "function") fMulerSelectPush(); } catch (eP) {}
  } catch (e) {}
}
